function opiszProdukt(nazwa, cena, dostepny) {
  return `${nazwa} - ${cena} zl (dostepny: ${dostepny ? "tak" : "nie"})`;
}

console.log(opiszProdukt("Laptop", 3200, true));
// Laptop - 3200 zl (dostepny: tak)

const cytat = 'Powiedzial: "Nie ma problemu"';
console.log(cytat); // Powiedzial: "Nie ma problemu"
// apostrof jako ogranicznik pozwolil uzyc cudzyslowu WEWNATRZ tekstu
// bez potrzeby escapowania - gdyby string byl w cudzyslowie,
// wewnetrzne cudzyslowy trzeba by poprzedzic znakiem \

function podsumujZamowienie(idZamowienia, kwota) {
  return `Zamowienie: ${idZamowienia}
Kwota: ${kwota} zl
Status: przyjete`;
}

console.log(podsumujZamowienie("Z-102", 249.99));
// Zamowienie: Z-102
// Kwota: 249.99 zl
// Status: przyjete

const liczba = 8;
console.log(`${liczba} do kwadratu to ${liczba ** 2}, a do szescianu to ${liczba ** 3}`);
// 8 do kwadratu to 64, a do szescianu to 512

const wiek = 30;
const zle = "Masz ${wiek} lat";
console.log(zle); // "Masz ${wiek} lat" - DOSLOWNIE, bez interpolacji

const dobrze = `Masz ${wiek} lat`;
console.log(dobrze); // "Masz 30 lat" - POPRAWNIE zinterpolowane

function formatujAdres(ulica, numer, miasto) {
  return `${ulica} ${numer}, ${miasto}`;
}

console.log(formatujAdres("Dluga", 15, "Krakow"));   // Dluga 15, Krakow
console.log(formatujAdres("Krotka", 3, "Gdansk"));    // Krotka 3, Gdansk
console.log(formatujAdres("Polna", 22, "Poznan"));    // Polna 22, Poznan

const a = 5;
const b = 12;
console.log(`Suma ${a} i ${b} to ${a + b}`); // Suma 5 i 12 to 17

function powitanieDnia(godzina) {
  return `${godzina < 12 ? "Dzien dobry" : godzina < 18 ? "Dzien dobry (popoludnie)" : "Dobry wieczor"}`;
}

console.log(powitanieDnia(9));  // Dzien dobry
console.log(powitanieDnia(15)); // Dzien dobry (popoludnie)
console.log(powitanieDnia(20)); // Dobry wieczor

function opiszTemperature(stopnie) {
  function kategoria(s) {
    if (s < 0) return "mroz";
    if (s < 15) return "chlodno";
    return "cieplo";
  }
  return `${stopnie} stopni - ${kategoria(stopnie)}`;
}

console.log(opiszTemperature(-5)); // -5 stopni - mroz
console.log(opiszTemperature(10)); // 10 stopni - chlodno
console.log(opiszTemperature(25)); // 25 stopni - cieplo

const produkty = ["chleb", "mleko", "jajka"];
console.log(`Lista zakupow zawiera ${produkty.length} produkty`);
// Lista zakupow zawiera 3 produkty

const uzytkownik = { imie: "Bartek", wiek: 32 };
console.log(`${uzytkownik.imie} ma ${uzytkownik.wiek} lata`);
// Bartek ma 32 lata

function wygenerujEtykiete(kod) {
  return `ETYKIETA-${kod.toUpperCase()}`;
}

console.log(wygenerujEtykiete("abc123")); // ETYKIETA-ABC123

const jednostka = "zl";
const kwota = 100;
const rabat = 0.1;
console.log(`Cena po rabacie: ${kwota - kwota * rabat} ${jednostka}`);
// Cena po rabacie: 90 zl

const tabelka = `Produkt | Cena
-------|------
Chleb   | 5 zl`;
console.log(tabelka);
// Produkt | Cena
// -------|------
// Chleb   | 5 zl

function porownajLiczby(a, b) {
  return `${a} jest ${a > b ? "wieksze" : a < b ? "mniejsze" : "rowne"} ${b}`;
}

console.log(porownajLiczby(5, 3)); // 5 jest wieksze 3
console.log(porownajLiczby(2, 8)); // 2 jest mniejsze 8
console.log(porownajLiczby(4, 4)); // 4 jest rowne 4

const pusteMiejsce = "";
console.log(`Dlugosc: ${pusteMiejsce.length}`); // Dlugosc: 0
console.log(typeof pusteMiejsce); // string

function zbudujNazweUzytkownika(imie, nazwisko) {
  return `${imie[0].toLowerCase()}.${nazwisko.toLowerCase()}`;
}

console.log(zbudujNazweUzytkownika("Jan", "Kowalski")); // j.kowalski

const szerokosc = 4;
const wysokosc = 6;
console.log(`Pole: ${szerokosc * wysokosc}, Obwod: ${2 * (szerokosc + wysokosc)}`);
// Pole: 24, Obwod: 20

function formatujListe(elementy) {
  return `Lista: ${elementy.join(", ")}`;
}

console.log(formatujListe(["jablko", "gruszka", "sliwka"]));
// Lista: jablko, gruszka, sliwka

const haslo = "sekret123";
console.log(`Haslo: ********`); // Haslo: ********
// (celowo NIE wypisujemy prawdziwego hasla - to swiadoma maskaradowa wartosc)

function generujRaportBledu(kod, wiadomosc) {
  return `BLAD ${kod}
Opis: ${wiadomosc}
Czas: sprawdz logi`;
}

console.log(generujRaportBledu(404, "Nie znaleziono zasobu"));
// BLAD 404
// Opis: Nie znaleziono zasobu
// Czas: sprawdz logi

function formatujProcent(liczba) {
  return `${(liczba * 100).toFixed(1)}%`;
}

console.log(formatujProcent(0.256)); // 25.6%

